// defaultStepSeconds is the fallback step size, in seconds, used when the query
// parameters do not specify a valid step.
const defaultStepSeconds uint64 = 60

// errNotImplemented is returned by the metric queries that are not yet
// supported by the ClickHouse metric store.
var errNotImplemented = errors.New("not implemented")

var _ metricstore.Reader = (*Reader)(nil)

// Reader queries aggregated span metrics (SPM) from ClickHouse.
type Reader struct {
	conn driver.Conn
}

// NewReader returns a new ClickHouse metric store Reader backed by the given
// ClickHouse driver connection.
func NewReader(conn driver.Conn) *Reader {
	return &Reader{conn: conn}
}

// GetLatencies returns the latency metrics for the requested services, grouped
// by service and, when requested, by operation.
func (r *Reader) GetLatencies(ctx context.Context, params *metricstore.LatenciesQueryParameters) (*metrics.MetricFamily, error) {
	query := sql.SelectLatencies
	familyName := "service_latencies"
	if params.GroupByOperation {
		query = sql.SelectLatenciesByOperation
		familyName = "service_operation_latencies"
	}

	step := stepSeconds(params.BaseQueryParameters)
	startTime, endTime := queryTimeRange(params.BaseQueryParameters)

	rows, err := r.conn.Query(ctx, query, step, params.Quantile, params.ServiceNames, startTime, endTime)
	if err != nil {
		return nil, fmt.Errorf("failed to query latencies: %w", err)
	}
	defer rows.Close()

	family := &metrics.MetricFamily{
		Name:    familyName,
		Type:    metrics.MetricType_GAUGE,
		Metrics: []*metrics.Metric{},
	}

	// metricKey identifies the timeseries a row belongs to. When operations are
	// not requested the operation component is left empty.
	type metricKey struct {
		service   string
		operation string
	}
	index := make(map[metricKey]*metrics.Metric)

	for rows.Next() {
		var row metricsRow
		if err := rows.ScanStruct(&row); err != nil {
			return nil, fmt.Errorf("failed to scan metrics row: %w", err)
		}

		key := metricKey{service: row.ServiceName}
		if params.GroupByOperation {
			key.operation = row.Operation
		}

		metric, ok := index[key]
		if !ok {
			labels := []*metrics.Label{{Name: "service_name", Value: row.ServiceName}}
			if params.GroupByOperation {
				labels = append(labels, &metrics.Label{Name: "operation", Value: row.Operation})
			}
			metric = &metrics.Metric{Labels: labels}
			index[key] = metric
			family.Metrics = append(family.Metrics, metric)
		}

		metric.MetricPoints = append(metric.MetricPoints, &metrics.MetricPoint{
			Timestamp: toDomainTimestamp(row.Timestamp),
			Value: &metrics.MetricPoint_GaugeValue{
				GaugeValue: &metrics.GaugeValue{
					Value: &metrics.GaugeValue_DoubleValue{DoubleValue: row.Value},
				},
			},
		})
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating metrics rows: %w", err)
	}

	return family, nil
}

