// stepSeconds converts the query step to a whole number of seconds. A nil,
// zero, or negative step falls back to defaultStepSeconds. Positive sub-second
// steps are clamped to 1 second and fractional seconds are truncated.
func stepSeconds(p metricstore.BaseQueryParameters) uint64 {
	if p.Step == nil {
		return defaultStepSeconds
	}
	step := *p.Step
	if step <= 0 {
		return defaultStepSeconds
	}
	seconds := step / time.Second
	if seconds < 1 {
		return 1
	}
	return uint64(seconds)
}

// convertSpanKinds maps OpenTelemetry span kind names to the lowercase values
// stored in ClickHouse. Unrecognized kinds are omitted from the result.
func convertSpanKinds(kinds []string) []string {
	converted := make([]string, 0, len(kinds))
	for _, kind := range kinds {
		switch kind {
		case "SPAN_KIND_SERVER":
			converted = append(converted, "server")
		case "SPAN_KIND_CLIENT":
			converted = append(converted, "client")
		case "SPAN_KIND_UNSPECIFIED":
			converted = append(converted, "")
		default:
			// Unknown span kinds are skipped.
		}
	}
	return converted
}

// queryTimeRange derives the inclusive [start, end] query window from the
// EndTime and Lookback parameters, using the current time as the end when it is
// not provided.
func queryTimeRange(p metricstore.BaseQueryParameters) (start, end time.Time) {
	end = time.Now()
	if p.EndTime != nil {
		end = *p.EndTime
	}
	start = end
	if p.Lookback != nil {
		start = end.Add(-*p.Lookback)
	}
	return start, end
}

// toDomainTimestamp converts a Go time.Time into the protobuf timestamp used by
// the metrics domain model.
func toDomainTimestamp(t time.Time) *types.Timestamp {
	return &types.Timestamp{
		Seconds: t.Unix(),
		Nanos:   int32(t.Nanosecond()),
	}
